// One flat warehouse row per dimension of each team's recent closed health checks.
// A dimension's `url` carries the id of the check it belongs to, which is what links
// it back to its team — that link survives both the per-team fan-out and pinned data.
const dim = $json;

// Items that arrived via On Error → Continue carry an `error` field instead of scores.
if (dim.error) {
  return { json: { __invalid: true, __failed: true, __error: `dimension fetch failed: ${dim.error}` } };
}

const checkId = String(dim.url ?? '').split('?')[0].split('/').pop();
const hc = $('Retrieve Latest Health Check').all().find((i) => i.json.id === checkId)?.json;
if (!hc) {
  return {
    json: {
      __invalid: true,
      __failed: true,
      __error: `dimension "${dim.name ?? '?'}" could not be traced back to its health check`,
    },
  };
}

// A dimension nobody rated has no aggregate. Writing it as nulls would drag every
// AVG() in the warehouse, so it is skipped — noted in the summary, but not an error.
if (typeof dim.ratings?.average !== 'number') {
  return {
    json: { __invalid: true, __failed: false, __error: `${hc.title}: nobody rated "${dim.name}"` },
  };
}

const r = dim.ratings;
return {
  json: {
    date: String(hc.date ?? '').slice(0, 10),
    team_id: hc.team?.id ?? '',
    team_name: hc.team?.name ?? '',
    health_check_id: hc.id,
    health_model: hc.healthModel?.name ?? null,
    dimension: dim.name,
    // Scales differ per health model — without them the averages are not comparable.
    scale_min: dim.scale?.min ?? hc.healthModel?.minRating ?? null,
    scale_max: dim.scale?.max ?? hc.healthModel?.maxRating ?? null,
    avg: r.average,
    min: r.min ?? null,
    max: r.max ?? null,
    stddev: r.stddev ?? null,
    count: r.count ?? null,
  },
};

// Runs exactly once per night: Merge Outcomes merges the written, skipped and
// invalid paths, so this fires after every team has been dealt with one way or another.
const allOf = (name) => {
  try {
    return $(name).all();
  } catch (e) {
    return []; // node never ran this execution
  }
};

const teams = allOf('Fetch Teams');
const checks = allOf('Retrieve Latest Health Check');
const rows = allOf('Normalize Health Check Data');
const written = allOf('Upsert Scores to Postgres');

const closed = checks.filter((i) => i.json.id && i.json.status === 'closed');
const teamsRolledUp = new Set(closed.map((i) => i.json.team?.id)).size;

// Every dimension-level failure already arrives here as an invalid row, so counting
// those plus the health-check lookups covers the run without double-reporting. A
// dimension nobody rated is not a failure: it is reported, but it never pages anyone.
const invalid = rows.filter((i) => i.json.__invalid);
const errors = [
  ...checks.filter((i) => i.json.error).map((i) => `• Health check lookup failed: ${i.json.error}`),
  ...invalid.filter((i) => i.json.__failed).map((i) => `• ${i.json.__error}`),
];
const unrated = invalid.filter((i) => !i.json.__failed).length;

const teamsSeen = teams.length;
const teamsSkipped = Math.max(teamsSeen - teamsRolledUp, 0);

return [
  {
    json: {
      teamsSeen,
      checksRolledUp: closed.length,
      teamsSkipped,
      rowsWritten: written.length,
      dimensionsUnrated: unrated,
      errorCount: errors.length,
      errors,
      summary: `${teamsSeen} team(s) seen · ${closed.length} closed check(s) rolled up · ${written.length} row(s) upserted · ${teamsSkipped} team(s) skipped · ${unrated} dimension(s) unrated · ${errors.length} error(s)`,
    },
  },
];

